// Schematic is a visual diagram editor component for drawing system schematics, control
// flows, and process diagrams. Schematics support interactive symbols, connection
// handles, and dynamic state visualization.
type Schematic struct {
	// Key is the unique identifier for this schematic.
	Key Key `json:"key" msgpack:"key"`
	// Name is a human-readable name for the schematic.
	Name string `json:"name" msgpack:"name"`
	// Nodes contains all diagram nodes in the schematic.
	Nodes []Node `json:"nodes" msgpack:"nodes"`
	// Edges contains all connections between nodes.
	Edges []Edge `json:"edges" msgpack:"edges"`
	// Configs contains per-node configuration keyed by node key. The variant of each
	// value selects the symbol it configures.
	Configs map[string]NodeConfig `json:"configs" msgpack:"configs"`
	// Group is the group the schematic sits in, if any.
	Group *group.Key `json:"group,omitzero" msgpack:"group,omitempty"`
	// Project is the project that holds the schematic.
	Project *project.Key `json:"project,omitzero" msgpack:"project,omitempty"`
}

// ApplyDefaults fills zero-valued fields with their schema-declared defaults.
func (s *Schematic) ApplyDefaults() {
	for i := range s.Edges {
		s.Edges[i].ApplyDefaults()
	}
	for key, value := range s.Configs {
		value.ApplyDefaults()
		s.Configs[key] = value
	}
}

// Validate returns an error wrapping validate.ErrValidation if any field violates its
// schema constraints.
func (s Schematic) Validate() error {
	v := validate.New("Schematic")
	v.NotEmptyString("name", s.Name)
	for i := range s.Edges {
		v.Exec(func() error { return validate.PathedError(s.Edges[i].Validate(), "edges", strconv.Itoa(i)) })
	}
	for key, value := range s.Configs {
		v.Exec(func() error { return validate.PathedError(value.Validate(), "configs", key) })
	}
	return v.Error()
}
